const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const subjectNames=['Physics','Chemistry','Mathematics'];
const subjectKeys=['Physics','Chemistry','Mathematics'];
const sampleSets={
 Physics:[
 ['A particle moves along a straight line with position $x(t)=t^3-6t^2+9t$. The magnitude of its acceleration at $t=2$ s is','0 m s⁻²','3 m s⁻²','6 m s⁻²','12 m s⁻²',2],
 ['A wire of resistance $R$ is stretched to twice its original length, with volume unchanged. Its new resistance is','2R','4R','R/2','R/4',1],
 ['A projectile is launched with speed $u$ at an angle $θ$ to the horizontal. Its maximum height is','u² sin θ / g','u² sin² θ / 2g','u² cos² θ / 2g','u² sin 2θ / g',1],
 ['A convex lens of focal length 20 cm forms a real image twice the size of the object. The object distance is','10 cm','20 cm','30 cm','40 cm',2],
 ['The de Broglie wavelength of an electron accelerated through potential $V$ is proportional to','V','√V','1/√V','1/V',2],
 ['A capacitor of capacitance $C$ is charged to potential $V$. The energy stored in it is','CV','CV²','½CV²','2CV²',2],
 ['The dimensional formula of Planck’s constant $h$ is','[ML²T⁻¹]','[MLT⁻²]','[ML²T⁻²]','[M⁰L²T⁻¹]',0],
 ['Two resistors of 4 Ω and 6 Ω are connected in parallel. Their equivalent resistance is','10 Ω','2.4 Ω','5 Ω','24 Ω',1],
 ['For simple harmonic motion, the acceleration is given by','a = ωx','a = −ω²x','a = ω²x','a = −ωx',1],
 ['A 2 kg body moving at 3 m s⁻¹ collides and sticks to a stationary 1 kg body. Their common speed is','1 m s⁻¹','2 m s⁻¹','3 m s⁻¹','6 m s⁻¹',1],
 ['The magnetic field at the centre of a circular loop of radius $R$, carrying current $I$, is','μ₀I/2R','μ₀I/R','μ₀IR/2','2μ₀I/R',0],
 ['The escape velocity from the surface of a planet of mass $M$ and radius $R$ is','√(GM/R)','√(2GM/R)','GM/R','2GM/R',1],
 ['In a series LCR circuit at resonance, the power factor is','0','½','1','infinite',2],
 ['The work done in moving a charge $q$ between two points at the same potential is','qV','zero','q/V','infinite',1],
 ['A wave has frequency 500 Hz and wavelength 0.68 m. Its speed is','170 m s⁻¹','340 m s⁻¹','680 m s⁻¹','1000 m s⁻¹',1]
 ],
 Chemistry:[
 ['The number of moles in 11 g of CO₂ is (molar mass = 44 g mol⁻¹)','0.10','0.20','0.25','0.50',2],
 ['Which of the following has the highest first ionisation enthalpy?','Na','Mg','Al','Si',3],
 ['The pH of a $1.0×10^{-3}$ M HCl solution at 25 °C is','1','2','3','11',2],
 ['The hybridisation of the central atom in $SF_6$ is','sp³','sp³d','sp³d²','dsp²',2],
 ['For a first-order reaction, the half-life is','proportional to initial concentration','inversely proportional to initial concentration','independent of initial concentration','proportional to its square',2],
 ['The oxidation number of chromium in $K_2Cr_2O_7$ is','+3','+4','+6','+7',2],
 ['Which molecule has a linear geometry?','H₂O','NH₃','CO₂','SO₂',2],
 ['The IUPAC name of $CH_3CH_2CHO$ is','propanone','propanal','ethanal','propanol',1],
 ['A buffer solution resists change in','temperature','volume','pH','pressure',2],
 ['The strongest intermolecular force present between water molecules is','London force','dipole-induced dipole','hydrogen bonding','ion-dipole force',2],
 ['For an ideal gas, the compressibility factor $Z$ is','0','1','RT','nRT',1],
 ['The conjugate base of $H_2PO_4^-$ is','$H_3PO_4$','$HPO_4^{2-}$','$PO_4^{3-}$','$OH^-$',1],
 ['Which is the most stable carbocation?','$CH_3^+$','$CH_3CH_2^+$','$(CH_3)_2CH^+$','$(CH_3)_3C^+$',3],
 ['The coordination number of Co in $[Co(NH_3)_6]^{3+}$ is','3','4','6','8',2],
 ['The value of Avogadro constant is approximately','6.022×10²³ mol⁻¹','6.022×10⁻²³ mol⁻¹','3.011×10²³ mol⁻¹','9.109×10⁻³¹ mol⁻¹',0]
 ],
 Mathematics:[
 ['If $f(x)=x^2+1$, then $f\prime(2)$ is','2','3','4','5',2],
 ['The value of $\int_0^1 2x\,dx$ is','0','1','2','4',1],
 ['The number of ways to arrange 4 distinct books on a shelf is','12','16','24','48',2],
 ['The distance between points $(1,2,3)$ and $(4,6,3)$ is','3','4','5','√41',2],
 ['The roots of $x^2-5x+6=0$ are','1, 6','2, 3','−2, −3','−1, −6',1],
 ['The determinant of $\begin{pmatrix}1&2\\3&4\end{pmatrix}$ is','−2','2','10','−10',0],
 ['If $\tan θ=1$ and $0<θ<π/2$, then $θ$ equals','π/6','π/4','π/3','π/2',1],
 ['The sum of the first $n$ natural numbers is','n²','n(n−1)/2','n(n+1)/2','2n+1',2],
 ['The slope of the line $3x−2y+5=0$ is','−3/2','3/2','2/3','−2/3',1],
 ['The probability of getting an even number on a fair six-sided die is','1/6','1/3','1/2','2/3',2],
 ['The solution of $\log_2 x=3$ is','6','8','9','16',1],
 ['The magnitude of vector $2\hat i−3\hat j+6\hat k$ is','5','6','7','9',2],
 ['The coefficient of $x^2$ in $(1+x)^5$ is','5','10','15','20',1],
 ['The limit $\lim_{x\to0}\frac{\sin x}{x}$ equals','0','1','∞','does not exist',1],
 ['The equation of a circle with centre $(0,0)$ and radius 3 is','$x+y=3$','$x²+y²=3$','$x²+y²=9$','$x²−y²=9$',2]
 ]
};
let files={pdf:null,key:null},settings={count:25,duration:180,mcq:20,numerical:5,correct:4,wrong:1},questions=[],attempt=null,currentIndex=0,activeSubject=0,timerId=null,startTime=0,reviewFilter='All questions',history=loadHistory();
function loadHistory(){try{return JSON.parse(localStorage.getItem('paperToCBTHistory')||'[]')}catch{return[]}}
function saveHistory(){localStorage.setItem('paperToCBTHistory',JSON.stringify(history));refreshHistory()}
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function openModal(id){$('#'+id).classList.add('show')}function closeModal(id){$('#'+id).classList.remove('show')}
function demoQuestions(){let out=[];subjectKeys.forEach((s,si)=>sampleSets[s].forEach((row,i)=>{out.push({id:`${si}-${i}`,number:i+1,subject:s,section:i<4?'A':'B',type:i<4?'mcq':'numerical',text:row[0],options:row.slice(1,5),answer:i<4?String.fromCharCode(65+row[5]):String([12,2.4,340,8,24][i-4]),response:'',visited:false,marked:false,seconds:0,images:[]})}));return out}
function setFiles(input,type){const f=input.files&&input.files[0];if(!f)return;const max=type==='pdf'?25:10;if(f.size>max*1024*1024){notify(`File is larger than ${max} MB.`);input.value='';return}files[type]=f;const label=type==='pdf'?'pdf':'key';$('#'+label+'-meta').textContent=f.name;$('#'+label+'-drop').classList.add('loaded');$('#'+label+'-drop').querySelector('.upload-plus').textContent='✓';}
$('#pdf-file').addEventListener('change',e=>setFiles(e.target,'pdf'));$('#key-file').addEventListener('change',e=>setFiles(e.target,'key'));
['pdf','key'].forEach(type=>{const el=$('#'+type+'-drop');el.addEventListener('dragover',e=>{e.preventDefault();el.classList.add('dragover')});el.addEventListener('dragleave',()=>el.classList.remove('dragover'));el.addEventListener('drop',e=>{e.preventDefault();el.classList.remove('dragover');const f=e.dataTransfer.files[0];if(f){const inp=$('#'+(type==='pdf'?'pdf-file':'key-file'));const dt=new DataTransfer();dt.items.add(f);inp.files=dt.files;setFiles(inp,type)}})});
function setProcessing(pct,stage){$('#processing').classList.add('show');$('#progress-fill').style.width=pct+'%';$('#processing-percent').textContent=pct+'%';$('#processing-stage').textContent=stage;let index=pct<20?0:pct<48?1:pct<78?2:3;$$('.stages span').forEach((x,i)=>x.classList.toggle('active',i===index))}
async function loadScript(src){return new Promise((resolve,reject)=>{let script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=reject;document.head.appendChild(script)})}
async function extractPdf(file){if(!file)return[];try{if(!window.pdfjsLib){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'}const bytes=await file.arrayBuffer(),pdf=await pdfjsLib.getDocument({data:bytes}).promise;let all='';for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),content=await page.getTextContent();all+='\n'+content.items.map(x=>x.str).join(' ')}return parseQuestions(all)}catch(e){console.warn('PDF text extraction unavailable',e);return[]}}
function parseQuestions(text){const normalized=text.replace(/\s+/g,' ').replace(/\b(?:Page\s*)?\d+\s*(?=\b(?:Q\.?\s*)?\d+[.)])/gi,' ');const matches=[...normalized.matchAll(/(?:^|\s)(?:Q\.?\s*)?(\d{1,3})\s*[.)](?=\s)/g)];let chunks=[];for(let i=0;i<matches.length;i++){let start=matches[i].index+matches[i][0].length,end=i+1<matches.length?matches[i+1].index:normalized.length;let n=+matches[i][1],chunk=normalized.slice(start,end).trim();if(n>0&&n<250&&chunk.length>18&&/(?:\(\s*[A-D1-4]\s*\)|[A-D][.)]\s|\([a-d]\))/i.test(chunk))chunks.push({number:n,text:chunk})}return chunks}
async function extractKey(file){if(!file)return{};try{if(!window.Tesseract)await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js');const result=await Tesseract.recognize(file,'eng');return parseAnswerKey(result.data.text)}catch(e){console.warn('OCR unavailable',e);return{}}}
function parseAnswerKey(text){let map={};const regex=/(?:Q\.?\s*)?(\d{1,3})\s*[.)\-:]?\s*(?:\(?\s*([A-D])\s*\)?|\(?\s*([1-4])\s*\)?|\(?\s*(I{1,3}|IV)\s*\)?)/gi;for(const m of text.matchAll(regex)){const n=+m[1],raw=(m[2]||m[3]||m[4]||'').toUpperCase();if(n>0&&n<250){const answer=/^[A-D]$/.test(raw)?raw:/^[1-4]$/.test(raw)?String.fromCharCode(64+Number(raw)):({I:'A',II:'B',III:'C',IV:'D'}[raw]);if(answer)map[n]=answer}}return map}
function subjectFor(i,total){const per=Math.ceil(total/3);return subjectKeys[Math.min(2,Math.floor(i/per))]}
function chunksToQuestions(chunks,answers){return chunks.map((c,i)=>{let raw=c.text,opts=[],m;const re=/\(?\s*([A-D])\s*\)?[.)]\s*([^\n]*?)(?=\s*\(?\s*[A-D]\s*\)?[.)]\s|$)/gi;while((m=re.exec(raw))&&opts.length<4)opts.push(m[2].trim());let qtext=opts.length?raw.slice(0,raw.search(/\(?\s*A\s*\)?[.)]\s/i)).trim():raw;if(!qtext)qtext=raw;let subj=subjectFor(i,chunks.length);let numerical=opts.length<2;return{id:'x'+i,number:c.number,subject:subj,section:numerical?'B':'A',type:numerical?'numerical':'mcq',text:qtext,options:opts.length===4?opts:['Option A','Option B','Option C','Option D'],answer:answers[c.number]||'',response:'',visited:false,marked:false,seconds:0,images:[]}})}
async function processUploads(){const name=$('#test-name').value.trim();if(!name){notify('Give your test a name first.');$('#test-name').focus();return}if(!files.pdf||!files.key){notify('Add both a PDF question paper and a JPG answer key.');return}$('#process-btn').disabled=true;$('#demo-btn').disabled=true;const stages=[['Reading your PDF…',10],['Finding numbered questions…',32],['Reading your answer key…',58],['Matching answers…',82]];let chunks=[],answers={};for(const [label,pct] of stages){setProcessing(pct,label);if(pct===10)chunks=await extractPdf(files.pdf);if(pct===58)answers=await extractKey(files.key);await new Promise(r=>setTimeout(r,400))}setProcessing(100,'Your review is ready');await new Promise(r=>setTimeout(r,300));questions=chunks.length?chunksToQuestions(chunks,answers):demoQuestions();if(!chunks.length){notify('Text extraction was unavailable; opening the editable practice set instead.')}prepareReview(name);$('#process-btn').disabled=false;$('#demo-btn').disabled=false}
$('#process-btn').addEventListener('click',processUploads);
function prepareReview(name){$('#review-title').textContent=`Review ${name}`;$('#review-summary').innerHTML=`<span>${questions.length} questions detected</span><span>${questions.filter(q=>q.answer).length} answers matched</span><span>Editable before exam</span>`;$('#review-list').innerHTML=questions.map((q,i)=>`<div class="review-row"><span class="review-num">${i+1}</span><textarea class="review-edit" data-q="${i}" aria-label="Edit question ${i+1}">${escapeHTML(q.text)}</textarea><div class="review-answer"><small>${escapeHTML(q.subject)} · ${q.type==='mcq'?'MCQ':'Numerical'}</small>${q.type==='mcq'?`<select data-answer="${i}" aria-label="Answer for question ${i+1}"><option value="">Answer unknown</option>${['A','B','C','D'].map((a,j)=>`<option value="${a}" ${q.answer===a?'selected':''}>${a}${q.options[j]?` · ${escapeHTML(q.options[j].slice(0,22))}`:''}</option>`).join('')}</select>`:`<input data-answer="${i}" value="${escapeHTML(q.answer)}" placeholder="Correct value" aria-label="Correct answer" />`}</div></div>`).join('');$$('.review-edit').forEach(el=>el.addEventListener('input',()=>questions[+el.dataset.q].text=el.value));$$('[data-answer]').forEach(el=>el.addEventListener('change',()=>questions[+el.dataset.answer].answer=el.value));openModal('review-modal')}
$('#demo-btn').addEventListener('click',()=>{if(!$('#test-name').value.trim())$('#test-name').value='JEE Practice · Demo';questions=demoQuestions();prepareReview($('#test-name').value.trim())});
$('#start-test').addEventListener('click',()=>{closeModal('review-modal');startExam()});
function startExam(){questions.forEach(q=>{q.response='';q.visited=false;q.marked=false;q.seconds=0});attempt={name:$('#test-name').value.trim()||'JEE Practice Test',startedAt:Date.now(),endedAt:null};currentIndex=0;activeSubject=0;startTime=Date.now();$('#exam-title').textContent=attempt.name;$('#exam-screen').classList.add('active');$('#result-screen').classList.remove('active');renderTabs();selectQuestion(0);runTimer();history.replaceState(null,'','#exam')}
function questionsBySubject(s){return questions.map((q,i)=>({q,i})).filter(x=>x.q.subject===subjectKeys[s])}
function renderTabs(){const counts=subjectKeys.map(s=>questions.filter(q=>q.subject===s).length);$('#subject-tabs').innerHTML=subjectKeys.map((s,i)=>`<button class="subject-tab ${i===activeSubject?'active':''}" data-subject="${i}">${s}<span>${counts[i]}</span></button>`).join('');$$('.subject-tab').forEach(b=>b.onclick=()=>{activeSubject=+b.dataset.subject;const first=questions.findIndex(q=>q.subject===subjectKeys[activeSubject]);renderTabs();selectQuestion(first>=0?first:0)})}
function selectQuestion(idx){if(idx<0||idx>=questions.length)return;const q=questions[idx];q.seconds=(q.seconds||0);currentIndex=idx;activeSubject=subjectKeys.indexOf(q.subject);if(activeSubject<0)activeSubject=0;q.visited=true;renderTabs();$('#exam-subject-name').textContent=q.subject;$('#exam-section-name').textContent=`Section ${q.section==='B'?'B · Numerical value':'A · MCQ'}`;$('#question-number-label').textContent=`Question ${String(q.number||idx+1).padStart(2,'0')}`;$('#section-indicator').textContent=q.type==='numerical'?'Section B · Numerical value':'Section A · Single correct';$('#question-kicker').innerHTML=`${escapeHTML(q.subject).toUpperCase()} <span>·</span> QUESTION ${String(q.number||idx+1).padStart(2,'0')}`;$('#question-text').textContent=q.text;$('#question-media').innerHTML=q.image?`<img src="${q.image}" alt="Question diagram" style="max-width:100%;margin-top:14px;border-radius:8px">`:'';$('#q-position').textContent=`${String(idx+1).padStart(2,'0')} / ${questions.length}`;if(q.type==='numerical'){$('#options').innerHTML=`<div class="numeric-input-wrap"><label for="numeric-answer">Enter your answer</label><input id="numeric-answer" class="numeric-input" inputmode="decimal" value="${escapeHTML(q.response)}" placeholder="Type your answer"/><div class="numpad">${['1','2','3','4','5','6','7','8','9','−','0','.','⌫','Clear'].map(k=>`<button data-key="${k}">${k}</button>`).join('')}</div></div>`;$('#numeric-answer').oninput=e=>{q.response=e.target.value.replace('−','-');renderPalette()};$$('[data-key]').forEach(b=>b.onclick=()=>numKey(b.dataset.key))}else{$('#options').innerHTML=q.options.map((o,i)=>`<div class="option ${q.response===String.fromCharCode(65+i)?'selected':''}" data-opt="${String.fromCharCode(65+i)}"><span class="option-letter">${String.fromCharCode(65+i)}</span><span class="option-copy">${escapeHTML(o)}</span></div>`).join('');$$('[data-opt]').forEach(el=>el.onclick=()=>{q.response=el.dataset.opt;renderQuestionOptions(q);renderPalette()})}$('#mark-review').textContent=q.marked?'⚑  Unmark review':'⚑  Mark for review';renderPalette()}
function renderQuestionOptions(q){$$('.option').forEach(el=>el.classList.toggle('selected',el.dataset.opt===q.response))}
function numKey(key){const input=$('#numeric-answer'),q=questions[currentIndex];if(!input)return;let v=input.value;if(key==='Clear')v='';else if(key==='⌫')v=v.slice(0,-1);else v+=key==='−'?'-':key;if((v.match(/-/g)||[]).length>1)v=v.replace(/-/g,'');const dots=(v.match(/\./g)||[]).length;if(dots>1)v=v.slice(0,v.lastIndexOf('.'));input.value=v;q.response=v;renderPalette()}
function renderPalette(){const list=questionsBySubject(activeSubject);$('#palette-subject-title').innerHTML=`${subjectKeys[activeSubject].toUpperCase()} <span>${list.length} QUESTIONS</span>`;$('#palette-grid').innerHTML=list.map(({q,i})=>{let cl=q.marked?(q.response?'answered-review':'review'):q.response?'answered':q.visited?'unanswered':'not-visited';return`<button class="palette-question ${cl} ${i===currentIndex?'current':''}" data-index="${i}" title="Question ${q.number||i+1}">${q.number||i+1}</button>`}).join('');$$('.palette-question').forEach(b=>b.onclick=()=>selectQuestion(+b.dataset.index))}
$('#clear-response').onclick=()=>{questions[currentIndex].response='';selectQuestion(currentIndex)};$('#mark-review').onclick=()=>{questions[currentIndex].marked=!questions[currentIndex].marked;selectQuestion(currentIndex)};$('#mark-next').onclick=()=>{questions[currentIndex].marked=true;nextQuestion()};$('#save-next').onclick=nextQuestion;$('#previous-question').onclick=()=>selectQuestion(currentIndex-1);function nextQuestion(){if(currentIndex<questions.length-1)selectQuestion(currentIndex+1);else notify('You’re at the last question. Submit when ready.')}
$('#mobile-palette').onclick=()=>$('#palette-panel').classList.toggle('mobile-open');$('#palette-close').onclick=()=>$('#palette-panel').classList.remove('mobile-open');const pp=$('#palette-panel');pp.id='palette-panel';
function runTimer(){clearInterval(timerId);let total=settings.duration*60;updateTimer(total);timerId=setInterval(()=>{total--;updateTimer(total);if(total<=0){clearInterval(timerId);submitTest(true)}},1000)}function updateTimer(sec){sec=Math.max(0,sec);const h=String(Math.floor(sec/3600)).padStart(2,'0'),m=String(Math.floor(sec%3600/60)).padStart(2,'0'),s=String(sec%60).padStart(2,'0');$('#timer').textContent=`${h}:${m}:${s}`;$('#timer').style.color=sec<300?'#d15849':''}
$('#submit-open').onclick=$('#palette-submit').onclick=()=>{const answered=questions.filter(q=>q.response!=='').length,marked=questions.filter(q=>q.marked).length;$('#submit-message').textContent=answered===questions.length?'All questions have a response. Ready to finish?':`You’ve answered ${answered} of ${questions.length} questions. You can still go back before submitting.`;$('#submit-summary').innerHTML=`<span><b>${answered}</b> answered</span><span><b>${questions.length-answered}</b> unanswered</span><span><b>${marked}</b> for review</span>`;openModal('submit-modal')};$('#confirm-submit').onclick=()=>{closeModal('submit-modal');submitTest(false)};
function evaluate(){let correct=0,wrong=0,unattempted=0;const bySubject={};for(const s of subjectKeys)bySubject[s]={correct:0,wrong:0,unattempted:0,score:0,total:0};questions.forEach(q=>{const b=bySubject[q.subject]||(bySubject[q.subject]={correct:0,wrong:0,unattempted:0,score:0,total:0});b.total++;if(!q.response){unattempted++;b.unattempted++}else if(q.answer&&String(q.response).trim().toLowerCase()===String(q.answer).trim().toLowerCase()){correct++;b.correct++;b.score+=settings.correct}else if(!q.answer){unattempted++;b.unattempted++}else{wrong++;b.wrong++;b.score-=settings.wrong}});return{correct,wrong,unattempted,bySubject,score:Object.values(bySubject).reduce((a,b)=>a+b.score,0),max:questions.length*settings.correct}}
function submitTest(auto){clearInterval(timerId);attempt.endedAt=Date.now();attempt.duration=Math.round((Date.now()-startTime)/1000);const r=evaluate();attempt.result=r;attempt.questions=questions.map(q=>({...q}));history.unshift(attempt);saveHistory();$('#exam-screen').classList.remove('active');renderResult(attempt,auto);history.replaceState(null,'','#result')}
